document.addEventListener('DOMContentLoaded',()=>{const yearEl=document.getElementById('current-year');if(yearEl)yearEl.textContent=new Date().getFullYear();document.querySelectorAll('.whatsapp-button').forEach(btn=>{btn.addEventListener('click',()=>{const location=btn.dataset.location||'unknown';if(typeof gtag==='function'){gtag('event','whatsapp_click',{event_category:'conversion',event_label:location,value:1})}if(typeof gtag==='function'){gtag('event','conversion',{send_to:'AW-XXXXXXXXX/YYYYYYY'})}})});const carouselBox=document.querySelector('.carousel-box');const track=document.querySelector('.carousel-track');const slides=document.querySelectorAll('.carousel-slide');const dots=document.querySelectorAll('.carousel-dots .dot');if(carouselBox&&track&&slides.length){let currentIndex=0;let autoPlayInterval=null;let startX=0;let isDragging=false;function goToSlide(index){if(index<0)index=slides.length-1;if(index>=slides.length)index=0;currentIndex=index;track.style.transform=`translateX(-${currentIndex*100}%)`;dots.forEach((dot,i)=>{dot.classList.toggle('active',i===currentIndex)})}function startAutoPlay(){stopAutoPlay();autoPlayInterval=setInterval(()=>{goToSlide(currentIndex+1)},3500)}function stopAutoPlay(){if(autoPlayInterval)clearInterval(autoPlayInterval)}carouselBox.addEventListener('mouseenter',stopAutoPlay);carouselBox.addEventListener('mouseleave',startAutoPlay);dots.forEach((dot,i)=>{dot.addEventListener('click',()=>{goToSlide(i)})});carouselBox.addEventListener('touchstart',(e)=>{stopAutoPlay();startX=e.touches[0].clientX;isDragging=true},{passive:true});carouselBox.addEventListener('touchmove',(e)=>{if(!isDragging)return;const currentX=e.touches[0].clientX;const diffX=startX-currentX;if(Math.abs(diffX)>35){if(diffX>0)goToSlide(currentIndex+1);else goToSlide(currentIndex-1);isDragging=false}},{passive:true});carouselBox.addEventListener('touchend',()=>{isDragging=false;startAutoPlay()});startAutoPlay()}});